(()=>{
 const out={},body=document.body;body.replaceChildren();body.style.cssText='margin:8px';
 const read=e=>{const r=e.getBoundingClientRect();return [r.x,r.y,r.width,r.height,e.offsetLeft,e.offsetTop,e.clientHeight]};
 for(const positioned of [false,true]){const parent=document.createElement('div');parent.style.cssText='width:200px;height:100px;border:3px solid;padding:5px;'+(positioned?'position:relative':'');body.append(parent);const middle=document.createElement('div');middle.style.cssText='margin:7px';parent.append(middle);const child=document.createElement('div');child.style.cssText='position:absolute;left:13px;top:17px;width:80px;height:20px';middle.append(child);out['offset'+positioned]=read(child);parent.remove()}
 for(const borderBox of [false,true]){const parent=document.createElement('div');parent.style.cssText='position:relative;width:200px;height:100px;border:3px solid;padding:5px';body.append(parent);const child=document.createElement('div');child.style.cssText='position:absolute;top:7px;bottom:11px;width:80px;border:2px solid;padding:4px;margin-top:3px;margin-bottom:5px;'+(borderBox?'box-sizing:border-box':'');parent.append(child);out['stretch'+borderBox]=read(child);parent.remove()}
 const sheet=document.createElement('style');sheet.textContent='.integration-ratio{display:block;position:relative;width:240px}.integration-ratio:before{content:"";display:block;padding-top:50%}.integration-ratio>div{position:absolute;top:0;bottom:0;width:100%}';document.head.append(sheet);const ratio=document.createElement('div');ratio.className='integration-ratio';ratio.innerHTML='<div><img style="width:100%;height:100%"></div>';body.append(ratio);out.generatedChildFirst=read(ratio.firstElementChild);out.generatedParent=read(ratio);ratio.remove();sheet.remove();
 const parent=document.createElement('div'),frame=document.createElement('iframe');parent.style.width='100px';frame.style.cssText='border:none;width:1px;height:1px';parent.append(frame);body.append(parent);out.inlineFrame=[parent.offsetHeight,parent.getBoundingClientRect().height,frame.getBoundingClientRect().height];parent.remove();
 const transformed=document.createElement('div');transformed.style.transform='translateX(2px)';body.append(transformed);out.computedTransform=getComputedStyle(transformed).transform;transformed.remove();
 body.style.margin='0';const clip=document.createElement('div');clip.style.cssText='width:200px';clip.innerHTML='<div style="display:inline-block;width:var(--absent,100%)"><a style="display:block"><div style="height:100%;overflow:hidden"><div style="height:0;padding-top:150%;position:relative"><div style="position:absolute;height:100%;width:100%"></div></div></div></a></div>';body.append(clip);out.staticPosition=Array.from(clip.querySelectorAll('*')).map(e=>{const r=e.getBoundingClientRect();return [r.x,r.y,r.width,r.height]});clip.remove();return out;
})()